import {GRASS,BUILDINGS,BUILDING_FACADES,BUILDING_ROOFS,buildingSettings,drawBuilding} from './scenery.js?v=20261006-race';
const $=s=>document.querySelector(s);
const keys=['type','width','depth','height','rotation','roof','facade','windows'];
const themes={medical:{facade:'concrete',roof:'white'},cafe:{facade:'brick',roof:'terracotta'},fuel:{facade:'concrete',roof:'white'},hospitality:{facade:'plaster',roof:'green'}};
export function mountScenery(api){
  const panel=document.createElement('section');panel.className='panel-section scenery-panel';
  panel.innerHTML=`<div class="section-heading"><span class="section-num">LAND</span><h2>Ground & buildings</h2></div><p class="field-hint">Grass fills the infield and empty ground, including the exported mod.</p><div class="grass-swatches">${Object.entries(GRASS).map(([k,v])=>`<button data-grass="${k}" aria-pressed="false"><i style="background:rgb(${v.color})"></i>${v.label}</button>`).join('')}</div><label class="toggle-row"><span>Grass blades in game · CSP</span><input id="grass-fx" type="checkbox" checked><span class="toggle"></span></label><p class="field-hint">Requires Custom Shaders Patch with Grass FX enabled.</p><div class="building-heading"><b id="building-heading">Building brush</b><span id="building-count" class="scene-tag"></span></div><label class="studio-field">Building type<select id="building-type">${Object.entries(BUILDINGS).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><div class="new-building-options" role="group" aria-label="New building types"><button data-building-type="cafe">☕ Café</button><button data-building-type="medical">✚ Medical</button><button data-building-type="fuel">▣ Fuel station</button><button data-building-type="hospitality">▤ Hospitality</button></div><div class="building-brush-preview"><canvas id="building-brush-preview" width="600" height="320" role="img" aria-label="Building footprint preview"></canvas><span id="building-preview-caption"></span></div><div class="studio-fields"><label class="studio-field">Width · m<input id="building-width" type="number" min="3" max="60" step="1"></label><label class="studio-field">Depth · m<input id="building-depth" type="number" min="3" max="40" step="1"></label><label class="studio-field">Height · m<input id="building-height" type="number" min="3" max="30" step="1"></label><label class="studio-field">Rotation · °<input id="building-rotation" type="number" min="0" max="359" step="1"></label></div><div class="building-rotation-controls"><input id="building-angle-slider" type="range" min="0" max="359" step="1" aria-label="Building rotation"><div><button data-rotate="-15">↶ −15°</button><button data-rotate="15">+15° ↷</button><button data-rotate="90">Turn 90°</button></div></div><label class="studio-field">Wall finish<select id="building-facade">${Object.entries(BUILDING_FACADES).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><div class="building-facade-swatches" role="group" aria-label="Wall finishes">${Object.entries(BUILDING_FACADES).map(([k,v])=>`<button data-facade="${k}" style="--finish:rgb(${v.color})" title="${v.label}" aria-label="${v.label}" aria-pressed="false"></button>`).join('')}</div><label class="studio-field">Roof finish<select id="building-roof">${Object.entries(BUILDING_ROOFS).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><label class="toggle-row"><span>Glass panels & windows</span><input id="building-windows" type="checkbox" checked><span class="toggle"></span></label><p class="field-hint">Ten building types with different geometry. Finishes and glass panels appear in 3D and the exported mod.</p><div class="analysis-actions"><button id="place-building" class="outline-button">Place building · U</button><button id="duplicate-building" class="outline-button" disabled>Duplicate nearby</button></div><button id="remove-building" class="tree-remove" hidden>Remove selected building</button><p class="field-hint">Use Move to select or drag a building. Rotate with its canvas handle, the slider, or R / Shift+R. Duplication preserves your dimensions and finishes.</p><div id="building-list" class="building-list"></div>`;
  $('.environment-panel').after(panel);
  panel.querySelectorAll('[data-grass]').forEach(b=>b.onclick=()=>api.updateTrack(t=>t.grass=b.dataset.grass));
  $('#grass-fx').onchange=()=>api.updateTrack(t=>t.export={...t.export,grassFx:$('#grass-fx').checked});
  $('#place-building').onclick=()=>{api.selectBuilding(-1);api.setTool('building');};
  $('#remove-building').onclick=()=>{const i=api.getBuilding();if(i>=0)api.updateTrack(t=>t.buildings.splice(i,1));};
  $('#duplicate-building').onclick=()=>api.duplicateBuilding();
  function apply(changed){
    const i=api.getBuilding(),values={...api.getBuildingBrush()};
    for(const key of keys){const input=$('#building-'+key);values[key]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(input.type==='number'&&!input.checkValidity()){api.toast('Use a value within the building dimensions shown.');refresh();return;}}
    if(changed==='type')Object.assign(values,BUILDINGS[values.type],themes[values.type]||{});
    const sanitized=buildingSettings(values);api.setBuildingBrush(sanitized);if(i>=0)api.updateTrack(t=>Object.assign(t.buildings[i],sanitized));refresh();
  }
  for(const key of keys)$('#building-'+key).onchange=()=>apply(key);
  panel.querySelectorAll('[data-building-type]').forEach(b=>b.onclick=()=>{$('#building-type').value=b.dataset.buildingType;apply('type');});
  panel.querySelectorAll('[data-facade]').forEach(b=>b.onclick=()=>{$('#building-facade').value=b.dataset.facade;apply('facade');});
  $('#building-angle-slider').oninput=()=>{$('#building-rotation').value=$('#building-angle-slider').value;drawPreview({...buildingSettings(readBrush()),rotation:Number($('#building-angle-slider').value)});};
  $('#building-angle-slider').onchange=()=>apply('rotation');panel.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=()=>api.rotateBuilding(Number(b.dataset.rotate)));
  function readBrush(){return Object.fromEntries(keys.map(k=>{const el=$('#building-'+k);return [k,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value];}));}
  function drawPreview(b){const canvas=$('#building-brush-preview'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,600,320);ctx.fillStyle='#e9efdf';ctx.fillRect(0,0,600,320);ctx.save();ctx.translate(300,145);const s=Math.max(b.width,b.depth,b.height)*1.5/250;drawBuilding(ctx,{...b,x:0,y:0},s,false,1);ctx.restore();$('#building-preview-caption').textContent=`${BUILDINGS[b.type].label} · ${b.width} × ${b.depth} m · ${b.height} m high`;
  }
  function refresh(){
    const t=api.getTrack(),i=api.getBuilding(),raw=t.buildings?.[i],b=buildingSettings(raw||api.getBuildingBrush());
    panel.querySelectorAll('[data-grass]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.grass===(t.grass||'mown'))));$('#grass-fx').checked=t.export?.grassFx!==false;
    $('#building-count').textContent=`${t.buildings?.length||0} / 60`;$('#building-heading').textContent=raw?`${BUILDINGS[b.type].label} ${i+1}`:'Building brush';
    for(const key of keys){const input=$('#building-'+key);if(input.type==='checkbox')input.checked=b[key];else input.value=b[key];}
    $('#building-angle-slider').value=b.rotation;$('#remove-building').hidden=!raw;$('#duplicate-building').disabled=!raw||(t.buildings||[]).length>=60;
    panel.querySelectorAll('[data-building-type]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.buildingType===b.type)));panel.querySelectorAll('[data-facade]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.facade===b.facade)));drawPreview(b);
    const list=$('#building-list');list.replaceChildren();(t.buildings||[]).forEach((v,index)=>{const button=document.createElement('button');button.textContent=`${BUILDINGS[v.type].label} ${index+1} · ${v.width} × ${v.depth} m`;button.classList.toggle('selected',index===i);button.onclick=()=>api.selectBuilding(index);list.append(button);});
  }
  return {refresh};
}
